    prog: 'hp', progLabel: 'Human Protection',
    year: 2014, variant: 'object', layout: 'plate', face: 'sans',
    opener: { big: 'A child does not stop at a jurisdiction. A case file does.', small: 'Indo\u2013Nepal Child Protection Forum' },
    sdg: ['SDG 16 \u00b7 Peace, justice and strong institutions', 'SDG 10 \u00b7 Reduced inequalities'],
